import Foundation
import CoreLocation

/// 内嵌机场库（IATA 三字码 → 坐标/名称/国家），源自开源 airports 数据集（6276 个）。
/// 纯离线：登机牌扫码后把机场三字码换成坐标，生成航线。数据以「lat|lon|name|country」压缩存储。
/// 数据来源：jbrooksuk/JSON-Airports（MIT License）。
enum AirportDB {

    struct Airport {
        let iata: String
        let lat: Double
        let lon: Double
        let name: String
        let country: String
        var coordinate: CLLocationCoordinate2D { .init(latitude: lat, longitude: lon) }
    }

    /// IATA → Airport（首次访问时解析一次）。
    static let all: [String: Airport] = {
        guard let data = raw.data(using: .utf8),
              let dict = try? JSONDecoder().decode([String: String].self, from: data) else { return [:] }
        var out = [String: Airport](minimumCapacity: dict.count)
        for (code, v) in dict {
            let p = v.split(separator: "|", maxSplits: 3, omittingEmptySubsequences: false)
            guard p.count == 4, let lat = Double(p[0]), let lon = Double(p[1]) else { continue }
            out[code] = Airport(iata: code, lat: lat, lon: lon, name: String(p[2]), country: String(p[3]))
        }
        return out
    }()

    /// 查机场（三字码不区分大小写）。
    static func lookup(_ iata: String) -> Airport? { all[iata.uppercased()] }

